export function buildAction02Prompt(
  context: Action02PromptContext
): Action02PromptOutput {
  const systemSourcesToAggregate = context.systemSources
    .sort((a, b) => b.priority - a.priority)
    .map((source) => `- ${source.systemName} (${source.systemId}): ${source.dataType}`)
    .join("\n");

  const aggregationRulesText = context.aggregationRules
    .map((rule) => {
      const sources = rule.sourceSystemIds.join(", ");
      return `- Aggregate ${sources} into ${rule.targetDataField} using ${rule.aggregationType}`;
    })
    .join("\n");

  const validationRulesText = context.dataValidationRules
    .map((rule) => {
      const constraints = [];
      if (rule.required) constraints.push("required");
      if (rule.minValue !== undefined) constraints.push(`min: ${rule.minValue}`);
      if (rule.maxValue !== undefined) constraints.push(`max: ${rule.maxValue}`);
      if (rule.allowedValues) constraints.push(`allowed: ${rule.allowedValues.join(", ")}`);
      return `- ${rule.fieldName} (${rule.dataType}): ${constraints.join(", ")}`;
    })
    .join("\n");

  const errorHandlingText = `
Connection Failure: ${context.errorHandlingStrategy.onConnectionFailure}
Data Validation Failure: ${context.errorHandlingStrategy.onDataValidationFailure}
Retry Attempts: ${context.errorHandlingStrategy.retryAttempts}
Retry Delay: ${context.errorHandlingStrategy.retryDelayMs}ms
Cache Expiration: ${context.errorHandlingStrategy.cacheExpirationMs}ms
  `.trim();

  const previousStateContext = context.previousAggregationResult
    ? `
Previous Aggregation (${context.previousAggregationResult.timestamp}):
- Systems Responded: ${context.previousAggregationResult.systemsResponded.join(", ")}
- Systems Failed: ${context.previousAggregationResult.systemsFailed.join(", ")}
- Validation Errors: ${context.previousAggregationResult.validationErrors.length}
    `.trim()
    : "No previous aggregation data available";

  const promptText = `
You are an AI agent responsible for aggregating real-time progress data from multiple systems.

## Data Sources to Aggregate
${systemSourcesToAggregate}

## Aggregation Rules
${aggregationRulesText}

## Data Validation Rules
${validationRulesText}

## Error Handling Strategy
${errorHandlingText}

## Previous State
${previousStateContext}

## Task
1. Connect to each system source in priority order
2. Retrieve the latest progress data from each system
3. Apply aggregation rules to combine data from multiple sources
4. Validate all aggregated data against validation rules
5. Handle any errors according to the error handling strategy
6. Return aggregated data in the specified format
7. Log any validation errors or connection issues

## Expected Output Format
{
  "aggregationTimestamp": "ISO8601 timestamp",
  "systemsQueried": ["system1", "system2"],
  "systemsSucceeded": ["system1", "system2"],
  "systemsFailed": [],
  "aggregatedData": {
    "progressMetrics": {},
    "delayedItems": [],
    "unsubmittedItems": [],
    "anomalies": []
  },
  "validationErrors": [],
  "cacheUsed": false,
  "retryCount": 0
}

## Validation Criteria
- All required fields must be present
- Data types must match specifications
- No duplicate entries in aggregated results
- Timestamps must be valid and recent
- All anomalies must be flagged with severity level
  `.trim();

  const instructions = [
    "Establish connections to all system sources in priority order",
    "Retrieve current progress data from each accessible system",
    "Apply deduplication rules to remove duplicate entries across systems",
    "Merge data from multiple sources according to aggregation rules",
    "Validate all fields against data validation rules",
    "Identify and flag any data anomalies or inconsistencies",
    "Handle connection failures according to error handling strategy",
    "Use cached data if system is unavailable and cache is valid",
    "Log all validation errors with severity levels",
    "Return complete aggregation result with metadata",
  ];

  const expectedOutputFormat = {
    aggregationTimestamp: "string (ISO8601)",
    systemsQueried: "string[]",
    systemsSucceeded: "string[]",
    systemsFailed: "string[]",
    aggregatedData: {
      progressMetrics: "Record<string, unknown>",
      delayedItems: "Array<{itemId: string, delayDays: number, reason: string}>",
      unsubmittedItems: "Array<{memberId: string, itemType: string, dueDate: string}>",
      anomalies: "Array<{type: string, severity: string, description: string}>",
    },
    validationErrors: "ValidationError[]",
    cacheUsed: "boolean",
    retryCount: "number",
  };

  const validationCriteria = [
    "aggregationTimestamp must be a valid ISO8601 timestamp",
    "systemsQueried must contain at least one system",
    "systemsSucceeded + systemsFailed must equal systemsQueried",
    "aggregatedData must contain all expected fields",
    "delayedItems must have itemId, delayDays, and reason",
    "unsubmittedItems must have memberId, itemType, and dueDate",
    "anomalies must have type, severity, and description",
    "validationErrors must include all detected validation failures",
    "No duplicate entries in any aggregated arrays",
    "All timestamps in aggregatedData must be recent (within last 24 hours)",
  ];

  return {
    systemId: "action-02",
    promptText,
    instructions,
    expectedOutputFormat,
    validationCriteria,
  };
}
